	name(EV_DISPATCH, "EV_DISPATCH")
	name(EV_DELETE, "EV_DELETE")
	name(EV_RECEIPT, "EV_RECEIPT")
	name(EV_ONESHOT, "EV_ONESHOT")
	name(EV_CLEAR, "EV_CLEAR")
	name(EV_EOF, "EV_EOF")
	name(EV_ERROR, "EV_ERROR")
